import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { register } from '../services/api';

export default function Register() {
  const navigate = useNavigate();
  const [form, setForm] = useState({ name:'', email:'', password:'', role:'STUDENT' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const submit = async (e) => {
    e.preventDefault(); setError(''); setLoading(true);
    try {
      const res = await register(form);
      if (res.data.success) {
        navigate('/verify-otp', { state: { email: form.email } });
      } else setError(res.data.message);
    } catch { setError('Server error'); }
    finally { setLoading(false); }
  };

  return (
    <div className="auth-page">
      <div className="auth-card">
        <div className="auth-logo">⚡ InternHub</div>
        <p className="auth-subtitle">Create your account and start applying</p>
        {error && <div className="alert alert-error">{error}</div>}
        <form onSubmit={submit}>
          {[
            { key:'name', label:'Full Name', type:'text', ph:'Rahul Sharma' },
            { key:'email', label:'Email', type:'email', ph:'you@example.com' },
            { key:'password', label:'Password', type:'password', ph:'Min 6 characters' },
          ].map(f => (
            <div className="form-group" key={f.key}>
              <label>{f.label}</label>
              <input className="form-control" type={f.type} value={form[f.key]}
                onChange={e => setForm({ ...form, [f.key]: e.target.value })} required placeholder={f.ph} />
            </div>
          ))}
          <div className="form-group">
            <label>I am a</label>
            <select className="form-control" value={form.role} onChange={e => setForm({ ...form, role: e.target.value })}>
              <option value="STUDENT">Student</option>
              <option value="ADMIN">Admin / Recruiter</option>
            </select>
          </div>
          <button className="btn btn-primary" type="submit" disabled={loading} style={{ width: '100%' }}>
            {loading ? 'Creating account…' : 'Create Account'}
          </button>
        </form>
        <p style={{ textAlign:'center', marginTop:'1.2rem', fontSize:'0.88rem', color:'var(--text2)' }}>
          Already registered? <Link to="/login" style={{ color:'var(--accent2)' }}>Sign in</Link>
        </p>
      </div>
    </div>
  );
}
